 public static void main(String[]args)throws Exception{var json=JsonParser.parseString(Files.readString(Path.of(args[0]))).getAsJsonArray().get(0).getAsJsonObject();var first=json.getAsJsonObject("numericPrograms").entrySet().iterator().next();var geom=new Gson().fromJson(first.getValue(),NumericPoseProgram.class).geometry();var a=row(geom,"alpha",1);var b=row(geom,"beta",1);var family=family(a,b);var exported=OriginalFiniteResourcePreparation.export(family,"s60_boundary");check(exported.inputs().size()==2,"field identity union");check(exported.inputs().get(0).name().equals("alpha0")&&exported.inputs().get(1).name().equals("beta0"),"field ordering");var resources=new PoseEngine.Resources(){public Optional<PoseProgram> program(Identifier i){return Optional.empty();}public Optional<FinitePoseProgram> finiteProgram(Identifier i){return Optional.of(exported.table());}public Optional<NumericPoseProgram> numericProgram(Identifier i){return Optional.ofNullable(exported.numericPrograms().get(i.toString()));}};var bound=new FinitePoseEngine().bind(geom,Map.of("program",exported.tableId()),Set.of("boolean.0","float.0","float.1"),resources).orElseThrow();for(int i=0;i<2;i++){var matrices=bound.evaluate(new PoseEngine.Inputs(0,0,0,0,0,true,Map.of("boolean.0",(float)i,"float.0",8f,"float.1",-24f))).orElseThrow();check(matrices.get(geom.parts().getFirst().id()).m30()==(i==0?.5f:-1.5f),"per-row input.0 aliases different source fields");}check(exported.equals(OriginalFiniteResourcePreparation.export(family,"s60_boundary")),"repeat export");var sixtyThree=row(geom,"z",63);check(OriginalFiniteResourcePreparation.export(family(sixtyThree,sixtyThree),"s60_boundary").inputs().size()==63,"64 total channels");var sixtyFour=row(geom,"z",64);bad(()->OriginalFiniteResourcePreparation.export(family(sixtyFour,sixtyFour),"s60_boundary"));var duplicate=new OriginalLinearPosePreparation.Prepared(a.program(),List.of(a.inputs().getFirst(),a.inputs().getFirst()),Map.of(),"a".repeat(64));bad(()->OriginalFiniteResourcePreparation.export(family(duplicate,b),"s60_boundary"));bad(()->OriginalFiniteResourcePreparation.export(family,"Bad namespace"));System.out.println("S60_EXPORT_BOUNDARY_PASS assertions="+count+" fieldAlias=distinct union64/65=true metadataOnly=true clientVeto=false");}
